const body = $input.first().json.body;
const required = ['event_name', 'sponsorship_package', 'asking_price', 'company_profile'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const price = parseFloat(body.asking_price);
if (isNaN(price) || price <= 0) return [{ json: { valid: false, error: 'asking_price must be a positive number' } }];
return [{ json: { valid: true, eventName: body.event_name.trim(), eventType: body.event_type||'conference', eventDate: body.event_date||'', eventLocation: body.event_location||'', expectedAttendees: parseInt(body.expected_attendees)||null, audienceDescription: (body.audience_description||'').slice(0,500), sponsorshipPackage: body.sponsorship_package.trim(), packageDescription: (body.package_description||'').slice(0,1000), askingPrice: price, currency: body.currency||'USD', companyProfile: body.company_profile.trim().slice(0,600), targetAudience: (body.target_audience||'').slice(0,400), marketingBudget: parseFloat(body.marketing_budget)||null, previousSponsorships: (body.previous_sponsorships||'').slice(0,400), competitorsSponsor: body.competitors_sponsor||'', replyEmail: body.reply_email||null, requestedAt: new Date().toISOString() } }];

const searchResult = $('Research Event').first().json;
const input = $('Validate Input').first().json;
const context = (searchResult.results||[]).map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,300)}`).join('\n');
return [{ json: { input, eventContext: context||'No additional context found.' } }];

