parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let evaluation;
try { evaluation = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
evaluation._meta = { eventName: input.eventName, sponsorshipPackage: input.sponsorshipPackage, askingPrice: input.askingPrice, currency: input.currency, replyEmail: input.replyEmail };
return [{ json: evaluation }];

const e = $input.first().json;
const m = e._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const cur = m.currency;
const verdictConfig = { strong_yes:{color:'#16a34a',bg:'#f0fdf4',label:'Strong Yes'}, yes_with_conditions:{color:'#2563eb',bg:'#eff6ff',label:'Yes with conditions'}, maybe:{color:'#d97706',bg:'#fffbeb',label:'Maybe'}, lean_no:{color:'#ea580c',bg:'#fff7ed',label:'Lean No'}, hard_no:{color:'#dc2626',bg:'#fef2f2',label:'Hard No'} };
const vc = verdictConfig[e.verdict]||verdictConfig.maybe;
const scoreBar = Array.from({length:10},(_,i)=>`<span style="display:inline-block;width:22px;height:10px;border-radius:2px;margin-right:2px;background:${i<Math.round((e.score||0)/10)?vc.color:'#e5e7eb'}"></span>`).join('');
const fitColors={excellent:'#16a34a',good:'#2563eb',moderate:'#d97706',poor:'#dc2626'};
const priceColors={underpriced:'#16a34a',fair:'#2563eb',slightly_inflated:'#d97706',overpriced:'#dc2626'};
const negoRows=(e.negotiation_recommendations||[]).map(n=>`<div style="border-left:3px solid #6366f1;padding:10px 14px;background:#f5f3ff;border-radius:0 6px 6px 0;margin-bottom:8px"><div style="font-size:14px;font-weight:600;color:#4338ca">${esc(n.ask)}</div><div style="font-size:13px;color:#555;margin-top:3px">${esc(n.rationale)}</div></div>`).join('');
const html=`<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111"><div style="max-width:680px;margin:0 auto"><div style="background:#111827;color:#fff;padding:20px 26px;border-radius:10px 10px 0 0"><div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:5px">Sponsorship Evaluation</div><div style="font-size:18px;font-weight:700">${esc(m.eventName)}</div><div style="font-size:13px;color:#9ca3af;margin-top:3px">${esc(m.sponsorshipPackage)} · ${cur}${m.askingPrice.toLocaleString()}</div></div><div style="background:${vc.bg};padding:16px 26px;border:1px solid ${vc.color}44;border-top:none;display:flex;align-items:center;gap:16px"><span style="background:${vc.color};color:#fff;font-size:12px;font-weight:700;padding:5px 14px;border-radius:20px">${vc.label}</span><div><div style="margin-bottom:4px">${scoreBar}</div><div style="font-size:13px;color:#555">${esc(e.one_line_take)}</div></div></div><div style="background:#fff;padding:18px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px"><div style="background:#f9fafb;padding:14px;border-radius:8px"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:4px">Audience fit</div><div style="font-size:15px;font-weight:700;color:${fitColors[e.audience_fit?.rating]||'#111'}">${esc(e.audience_fit?.rating||'?')}</div><div style="font-size:13px;color:#555;margin-top:4px;line-height:1.5">${esc(e.audience_fit?.reasoning)}</div></div><div style="background:#f9fafb;padding:14px;border-radius:8px"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:4px">Price assessment</div><div style="font-size:15px;font-weight:700;color:${priceColors[e.value_assessment?.price_fairness]||'#111'}">${esc((e.value_assessment?.price_fairness||'?').replace(/_/g,' '))}</div>${e.value_assessment?.cost_per_attendee?`<div style="font-size:13px;color:#9ca3af">${cur}${e.value_assessment.cost_per_attendee.toFixed(2)}/attendee</div>`:''}<div style="font-size:13px;color:#555;margin-top:4px;line-height:1.5">${esc(e.value_assessment?.price_reasoning)}</div></div></div></div><div style="background:#fff;padding:18px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Package quality</div><div style="font-size:14px;color:#374151;line-height:1.65;margin-bottom:12px">${esc(e.package_quality?.assessment)}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#16a34a;margin-bottom:5px">Strong</div>${(e.package_quality?.strong_elements||[]).map(s=>`<div style="font-size:13px;color:#374151;padding:3px 0">+ ${esc(s)}</div>`).join('')}</div><div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#dc2626;margin-bottom:5px">Weak/missing</div>${(e.package_quality?.weak_elements||[]).map(w=>`<div style="font-size:13px;color:#374151;padding:3px 0">− ${esc(w)}</div>`).join('')}</div></div></div><div style="background:#fff;padding:18px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Strategic considerations</div>${(e.strategic_considerations||[]).map(s=>`<div style="font-size:14px;color:#374151;padding:6px 0;border-bottom:1px solid #f3f4f6;line-height:1.5">→ ${esc(s)}</div>`).join('')}</div>${(e.risks||[]).length?`<div style="background:#fffbeb;padding:14px 26px;border:1px solid #fde68a"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:7px">Risks</div>${(e.risks||[]).map(r=>`<div style="font-size:14px;color:#78350f;padding:4px 0">⚠ ${esc(r)}</div>`).join('')}</div>`:''  }${negoRows?`<div style="background:#fff;padding:18px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Negotiation recommendations</div>${negoRows}</div>`:''  }${e.counter_offer_suggestion?`<div style="background:#f0fdf4;padding:14px 26px;border:1px solid #bbf7d0"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:5px">Counter-offer suggestion</div><div style="font-size:14px;color:#166534;line-height:1.6">${esc(e.counter_offer_suggestion)}</div></div>`:''  }${(e.questions_before_committing||[]).length?`<div style="background:#f8faff;padding:14px 26px;border:1px solid #c7d7f5"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:7px">Ask before signing</div>${(e.questions_before_committing||[]).map((q,i)=>`<div style="font-size:14px;color:#1e3a8a;padding:5px 0;border-bottom:1px solid #dbeafe">${i+1}. ${esc(q)}</div>`).join('')}</div>`:''  }<div style="background:#111827;color:#4b5563;font-size:11px;padding:12px 26px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">Sponsorship Evaluator · ${new Date().toLocaleDateString()}</div></div></body></html>`;
return [{ json: { html, replyEmail: m.replyEmail, eventName: m.eventName, verdict: e.verdict, score: e.score, evaluation: e } }];
